// Behaviour test for libvorbis psy.c setup_tone_curves (retail 0x00C91AB0): a copy of the tone-curve builder (with the min / max /
// attenuate helpers it calls) over synthetic ATH and tonemasks tables -- every band gets P_LEVELS curves of EHMER_MAX bins plus the
// two fenceposts (first / last bin above -200 dB), levels stay ordered after the ATH overlay and the loud-curve limiting, and a
// centre boost raises a curve by at most the boost.
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <cmath>
#define P_BANDS 17      /* 62Hz to 16kHz */
#define P_LEVELS 8      /* 30dB to 100dB */
#define P_LEVEL_0 30.   /* 30 dB */
#define P_NOISECURVES 3
#define NOISE_COMPAND_LEVELS 40
#define MAX_ATH 88
#define EHMER_OFFSET 16
#define EHMER_MAX 56
#define VE_BANDS 7
#define PACKETBLOBS 15
#define toOC(n)     (log(n)*1.442695f-5.965784f)
#define fromOC(o)   (exp(((o)+5.965784f)*.693147f))
#define toBARK(n)   (13.1f*atan(.00074f*(n))+2.24f*atan((n)*(n)*1.85e-8f)+1e-4f*(n))
