static int fail(const char* what) { std::printf("%s\n00c91ab0_TEST FAIL\n", what); return 1; }

int main()
{
    int i, j, m, b;
    float att[P_BANDS];
    /* synthetic tables: a quiet ATH (-20 dB rising 0.25 dB per entry), tone masks that fall off 1 dB per bin from the centre
       and rise 10 dB per level (the 50..100 dB curves) */
    for (i = 0; i < MAX_ATH; i++) ATH[i] = -20.f + 0.25f * i;
    for (b = 0; b < P_BANDS; b++) for (j = 0; j < 6; j++) for (i = 0; i < EHMER_MAX; i++)
