        float ***c = setup_tone_curves(att, binHz, n, 0.f, 0.f);
        if (!c) return fail("alloc");
        for (b = 0; b < P_BANDS; b++) {
            if (!c[b]) return fail("band alloc");
            for (m = 0; m < P_LEVELS; m++) {
                float *cur = c[b][m]; int lo = (int)cur[0], hi = (int)cur[1];
                if (!cur) return fail("level alloc");
                /* fenceposts: first / last bins above -200 dB, with the centre inside */
                if (lo < 0 || lo > EHMER_OFFSET || hi < EHMER_OFFSET + 1 || hi > EHMER_MAX - 1) return fail("fenceposts");
                for (j = 0; j < lo; j++) if (cur[j + 2] > -200.f) return fail("lo fencepost");
